.move-down {
  margin-left: auto;
  margin-right: auto;   /* centers horizontally */
  width: 95%;  
}

/* Column widths (based on your slots) */
column-unit[slot="0"] { flex: 0 0 72%; }  /* first column: slideshow */
column-unit[slot="1"] { flex: 0 0 28%; }  /* second column: text or other content */

.more-text {
  max-height: 0;
  overflow: hid2en;
  transition: max-height 0.5s ease;
}

.descrip-com {
    line-height: 1.2;
    margin-bottom: 1.35rem; 
    margin-top: -0.7rem; 
    font-size: 1.35rem;"
}




.more-text.active {
  max-height: 1000px; /* big enough for any content */
}


.buttons {
    background-color: #ffffff; /* Grey background */
    color: #000000; 
    font: 13px;
    margin-top: 1.5rem; /* space above button */
}

.buttons:hover {
    filter: brightness(30%); /* Slightly darkens on hover */
}

.icons{
	margin-top: 0px;
    line-height: 2;
    margin-top: 2rem;
}

.page-content {
  padding-top: 3.23rem;
}

column-set[gutter="1.rem"] {
  margin-top: 0rem; /* flytter hele blocken op */
}




[id="N1293170296"].page {
	background-color: #000000;
}


column-unit[slot="0"] gallery-slideshow {
  transform: translateY(4.5rem);
}


/* Base styles (default for very small screens, <900px) */
.project-text {
  font-size: 0.75rem;
  line-height: 1.35;
  opacity: 0.9;
}

.descrip-com {
  font-size: 1rem;
  line-height: 1.2;
  margin-top: -0.5rem;
  margin-bottom: 0.95rem;
}

.details {
  font-family: "Diatype Variable";
  font-weight: 500;
  font-style: normal;
  font-variation-settings: 'slnt' 0, 'MONO' 0;
  font-size: 0.9rem;
  line-height: 1.45;
  margin-top: 0.15rem;
  margin-bottom: 0.85rem;
  opacity: 1;
  color: #ffffff;
}

/* Medium screens (min-width: 1020px) */
@media (min-width: 1020px) {
    .project-text {
    font-size: 1rem;
    line-height: 1.25;
    opacity: 0.9; 
  }

  .descrip-com {
    font-size: 1.10rem;
    line-height: 1.3;
    margin-top: -0.75rem;
    margin-bottom: 1.1rem; 
  }
    h2 {
  font-size: 1.3rem;
  margin-bottom: -0.4rem;
}

    .project-title {
    line-height: 1.3;
    font-size: 1.25rem;  
    margin-bottom: 1.35rem; 
    margin-top: -0.7rem; 
    font-size: 1.4rem;"
}



    .view-full-project {
    font-size: 1.2rem;
    position: relative;
    display: inline-block;
    color: #ffffff;
    text-decoration: none;
    margin-bottom: 0.5rem; 
    transition: color 0.3s ease;
}

.view-full-project::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 3px;
    width: 100%;
    height: 1.5px;
    background: currentColor;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.3s ease;
}

.view-full-project:hover {
    color: white;
}

.view-full-project:hover::after {
    transform: scaleX(1);
}

  .details {
    font-size: 1.2rem;
    line-height: 1.65;
    margin-top: -0.1;
    margin-bottom: 0.9rem;
  }
}

/* Large screens (min-width: 1490px) */
@media (min-width: 1490px) {
.project-text {
    font-size: 1.05rem;
    line-height: 1.35;
    opacity: 0.9; 
  }

  .descrip-com {
    font-size: 1.25rem;
    line-height: 1.25;
    margin-top: -0.85rem;
    margin-bottom: 1.25rem;
  }

    .project-title {
    line-height: 1.2;
    margin-bottom: 1.35rem; 
    margin-top: -0.7rem; 
    font-size: 1.45rem;"
}

  h2 {
    font-size: 1.65rem;
    margin-bottom: -0.4rem;
  }

  .details {
    font-size: 1.20rem;
    line-height: 1.75;
    margin-top: 0;
    margin-bottom: 0.5rem;
  }

  .view-full-project {
    position: relative;
    font-size: 1.25rem;  
    display: inline-block;
    color: #d1d1d1;
    text-decoration: none;
    margin-bottom: 0.25rem; 
    transition: color 0.3s ease;
}

.view-full-project::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 3px;
    width: 100%;
    height: 1.5px;
    background: currentColor;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.3s ease;
}

.view-full-project:hover {
    color: white;
}

.view-full-project:hover::after {
    transform: scaleX(1);
}

}


@media (max-width: 850px) {
  .project-text {
    font-size: 0.75rem;
    line-height: 1.4;
    opacity: 0.9; 
  }

  .descrip-com {
    font-size: 0.4rem;
    line-height: 1.25;
    margin-top: -0.5rem;
    margin-bottom: 1.15rem; 
  }

  h2 {
    font-size: 1.355rem;
    margin-bottom: -0.5rem;
  }

  .details {
    font-size: 1.05rem;
    line-height: 1.75;
    margin-top: 0rem;
    margin-bottom: 0.9rem;
  }
}




/* Add more general scaling */
.icons3 {
  width: 100%;
  height: auto;
  max-width: 1.75rem; /* Ensure max width is respected */
}
